import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

class Solution {
    private static class State {
        TreeNode node;
        int sum;
        State(TreeNode node, int sum) { this.node = node; this.sum = sum; }
    }

    public boolean hasPathSum(TreeNode root, int targetSum) {
        if (root == null) {
            return false;
        }
        List<Integer> leafSums = new ArrayList<>();
        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State(root, root.val));
        while (!stack.isEmpty()) {
            State state = stack.pop();
            TreeNode node = state.node;
            if (node.left == null && node.right == null) {
                leafSums.add(state.sum);
            } else {
                if (node.right != null) {
                    stack.push(new State(node.right, state.sum + node.right.val));
                }
                if (node.left != null) {
                    stack.push(new State(node.left, state.sum + node.left.val));
                }
            }
        }
        return leafSums.contains(targetSum);
    }
}

